"""Retain the latest original coin algorithm and existing Root dialog ownership seam."""
from v029_video_feedback import function
from v029_comment_search import whole_proof
RECIPES={'unique same-subject open and close generation without numeric overflow': {'before': '    private var tripleCelebrationSequence = 0L', 'after': '    private var tripleCelebrationSequence = 0L\n    private var coinDialogGeneration: Any = Any()'}, 'original close invalidates only the current coin request under existing entry admission': {'before': '    fun setCoinDialogVisible(visible: Boolean) {\n        updateOwned { it.copy(coinDialogVisible = visible) }\n    }', 'after': '    fun setCoinDialogVisible(visible: Boolean) {\n        environment.commit {\n            val current = _uiState.value\n            if (!visible) {\n                coinDialogGeneration = Any()\n                current.desktopCoinDialogRequest?.retireUnderAdmission()\n            }\n            _uiState.value = current.copy(coinDialogVisible = visible,\n                desktopCoinDialogRequest = if (visible) current.desktopCoinDialogRequest else null)\n        }\n    }'}, 'full original balance algorithm keeps zero-argument caller and checks final request generation and source admission': {'before': '    fun openCoinDialog() {\n        val state = _uiState.value\n        val capturedSubject = state.subject\n        if (state.coinCount >= state.coinLimit) {\n            emitMessage(if (state.isRepost) "转载视频最多投1个硬币" else "已投满2个硬币")\n            return\n        }\n        updateOwned { it.copy(coinDialogVisible = true, userCoinBalance = null) }\n        viewModelScope.launch {\n            currentCoroutineContext().ensureActive(); environment.assertOwned();\n\n            val balance = coinBalanceLoader.load()\n            currentCoroutineContext().ensureActive(); environment.assertOwned()\n            if (_uiState.value.subject?.generation != capturedSubject?.generation) return@launch\n            updateOwned { current ->\n                if (current.coinDialogVisible) current.copy(userCoinBalance = balance) else current\n            }\n        }\n    }', 'after': '    fun openCoinDialog() {\n        openCoinDialogWithDesktopRequest(null)\n    }\n\n    internal fun openCoinDialogWithDesktopRequest(request: com.bilipai.desktop.ui.DesktopWindowsVideoCoinDialogRequest?) {\n        val state = _uiState.value\n        val capturedSubject = state.subject\n        if (request != null && (request.subject != capturedSubject || !request.isOwned())) return\n        if (state.coinCount >= state.coinLimit) {\n            val message = if (state.isRepost) "转载视频最多投1个硬币" else "已投满2个硬币"\n            if (request == null) emitMessage(message)\n            else viewModelScope.launch(request.context) {\n                if (request.isOwned()) emitMessage(message)\n            }\n            return\n        }\n        val capturedGeneration = Any()\n        var opened = false\n        val publishOpen = {\n            environment.commit {\n                val current = _uiState.value\n                if (current.subject == capturedSubject && current.coinCount < current.coinLimit &&\n                    (request == null || request.isOwned())) {\n                    coinDialogGeneration = capturedGeneration\n                    current.desktopCoinDialogRequest?.retireUnderAdmission()\n                    _uiState.value = current.copy(coinDialogVisible = true, userCoinBalance = null,\n                        desktopCoinDialogRequest = request)\n                    opened = true\n                }\n            }\n        }\n        if (request == null) publishOpen() else if (!request.admit(publishOpen)) return\n        if (!opened) return\n        viewModelScope.launch(request?.context ?: EmptyCoroutineContext) {\n            currentCoroutineContext().ensureActive(); environment.assertOwned();\n\n            if (request != null && !request.isOwned()) return@launch\n            val balance = coinBalanceLoader.load()\n            currentCoroutineContext().ensureActive(); environment.assertOwned()\n            if (_uiState.value.subject?.generation != capturedSubject?.generation) return@launch\n            val publishBalance = {\n                environment.commit {\n                    val current = _uiState.value\n                    if (coinDialogGeneration === capturedGeneration && current.coinDialogVisible &&\n                        current.subject?.generation == capturedSubject?.generation &&\n                        current.desktopCoinDialogRequest === request &&\n                        (request == null || request.isOwned())) {\n                        _uiState.value = current.copy(userCoinBalance = balance)\n                    }\n                }\n            }\n            if (request == null) publishBalance() else request.admit(publishBalance)\n        }\n    }'}, 'original coin mutation accepts an optional exact originating dialog without changing legacy callers': {'before': '    internal fun doCoinWithDesktopPresentation(count: Int, alsoLike: Boolean,\n        presentation: DesktopOriginalVideoEngagementPresentation? = null\n    ) {', 'after': '    internal fun doCoinWithDesktopPresentation(count: Int, alsoLike: Boolean,\n        presentation: DesktopOriginalVideoEngagementPresentation? = null,\n        request: com.bilipai.desktop.ui.DesktopWindowsVideoCoinDialogRequest? = null\n    ) {'}, 'confirm consumes the same visible request and current allowance once before original API launch': {'before': '        if (presentation == null) setCoinDialogVisible(false)\n        else if (!presentation.admit { setCoinDialogVisible(false) }) return', 'after': '        var consumed = false\n        val consumeDialog = {\n            val current = _uiState.value\n            if (current.subject == state.subject &&\n                count in 1..(current.coinLimit - current.coinCount).coerceIn(0, current.coinLimit) &&\n                (request == null || (current.desktopCoinDialogRequest === request &&\n                    current.coinDialogVisible && request.subject == current.subject &&\n                    request.matchesPresentation(presentation) && request.isOwned()))) {\n                setCoinDialogVisible(false)\n                consumed = true\n            }\n        }\n        if (presentation == null) environment.commit(consumeDialog)\n        else if (!presentation.admit { environment.commit(consumeDialog) }) return\n        if (!consumed) return'}}
def apply(path,text,parser):
    if path!='com/android/purebilibili/feature/video/viewmodel/VideoEngagementViewModel.kt':return text,None
    before=text
    def exact(old,new,label):
        nonlocal text
        assert text.count(old)==1,(label,text.count(old))
        text=text.replace(old,new,1)
    label='unique same-subject open and close generation without numeric overflow'
    exact(RECIPES[label]['before'],RECIPES[label]['after'],label)
    anchor='data class VideoEngagementUiState(\n'
    exact(anchor,anchor+'    val desktopCoinDialogRequest: com.bilipai.desktop.ui.DesktopWindowsVideoCoinDialogRequest? = null,\n','Existing model owns the same dialog request')
    label='original close invalidates only the current coin request under existing entry admission'
    exact(RECIPES[label]['before'],RECIPES[label]['after'],label)
    old=function(text,'openCoinDialog',parser)
    normalized=old.replace('        val capturedSubject = _uiState.value.subject\n        val state = _uiState.value',
                           '        val state = _uiState.value\n        val capturedSubject = state.subject',1)
    label='full original balance algorithm keeps zero-argument caller and checks final request generation and source admission'
    assert normalized==RECIPES[label]['before'],'Latest balance algorithm changed beyond the retained captured-request seam'
    exact(old,RECIPES[label]['after'],label)
    label='original coin mutation accepts an optional exact originating dialog without changing legacy callers'
    exact(RECIPES[label]['before'],RECIPES[label]['after'],label)
    label='confirm consumes the same visible request and current allowance once before original API launch'
    exact(RECIPES[label]['before'],RECIPES[label]['after'],label)
    exact('        environment.commit { _uiState.value = VideoEngagementUiState(',
          '        environment.commit {\n            previous.desktopCoinDialogRequest?.retireUnderAdmission()\n            coinDialogGeneration = Any()\n            _uiState.value = VideoEngagementUiState(',
          'Subject/session replacement retires the old dialog only under the existing admission')
    proof=whole_proof(before,text)
    proof.update(wholeLatestCoinLimitAndMutationAlgorithmsRetained=True,
                 sameExistingCoinDialogRequestReused=True,
                 balanceIoRemainsOutsideAdmission=True,
                 sourceQualified=False)
    return text,proof

